/**
 * emit to subscription queries of type FindTimeSeries,
 * but only if the id matches
 *
 * @param		entity	TimeSeries
 */
	protected void emitFindTimeSeries( TimeSeries entity ) {
		LOGGER.info("handling emitFindTimeSeries" );
		
	    queryUpdateEmitter.emit(FindTimeSeriesQuery.class,
	                            query -> query.getFilter().getTimeSeriesId().equals(entity.getTimeSeriesId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTimeSeries
	 * 
	 * @param		entity	TimeSeries
	 */
	protected void emitFindAllTimeSeries( TimeSeries entity ) {
		LOGGER.info("handling emitFindAllTimeSeries" );
		
	    queryUpdateEmitter.emit(FindAllTimeSeriesQuery.class,
	                            query -> true,
	                            entity);
	}

